/// <summary>
/// NDX_MultipleSelect_KBV_BuildingProject
/// </summary>
class NDX_MultipleSelect_KBV_BuildingProject extends NDX_MultipleSelect
{
    NDXMultipleS_KBV_BuildingProject    nDX_SelectionTmp;        // Vorlagedaten für die Selektion der bereits markierten Datensätze
    KCS_KBVBuildingProjectID            bvId;
    KCS_KBVBuildingProjectTable         lKCS_KBVBuildingProjectTable;

}

Method.Source:
void closedSelectForm()
{
    FormDataSource  formDatasource;
    int             i, nBis;
    tableId         tableId;

    nBis = selectForm.dataSourceCount();
    for (i = 1; i <= nBis; i++)
    {
        formDataSource  = selectForm.dataSource(i);
        tableId         = formDataSource.table();
        if (tableId == tablenum(NDXMultipleS_KBV_BuildingProject))
        {
            nDX_SelectionTmp.data(formDatasource.cursor());
            break;
        }
    }
}
